/**
 * Root-cause regression suite for the journal message
 *
 *     TypeError: undefined is not a function
 *
 * seen when running strategies containing the "analyse Turbo recovery across
 * markets" / "Turbo markets analysis" blocks.
 *
 * THE BUG
 * ───────
 * Blockly blocks generate plain bot-code calls such as
 * `Bot.ntAnalyseTurboMarkets(...)`. The sandboxed interpreter builds `Bot`
 * from the trade-engine Interface — every ticks call lives in
 * TicksInterface.js — and the js-interpreter throws literally
 * "<callee> is not a function" when bot code invokes an undefined property.
 * TicksInterface exposed the single-market `ntAnalyseTurboRecovery` pair but
 * NOT the multi-market `ntAnalyseTurboMarkets` / `ntTurboMarketsDecision`
 * pair the engine (Ticks.js) implements and the blocks emit, so any strategy
 * using those blocks crashed the first time it reached them.
 *
 * The first two tests pin the failure mechanism to the REAL
 * @deriv/js-interpreter; the rest guard every other nt* bridge so a new
 * block-to-engine call cannot ship without its interface entry.
 */
import JSInterpreter from '@deriv/js-interpreter';
import getTicksInterface from '../TicksInterface';

/** Engine stub whose every method is an auto-created jest.fn. */
const makeEngine = () => new Proxy({}, { get: (target, key) => (target[key] ??= jest.fn()) });

const runBotScriptOnce = (bot_native, script) => {
    const interpreter = new JSInterpreter(script, (js_interpreter, scope) => {
        js_interpreter.setProperty(scope, 'Bot', js_interpreter.nativeToPseudo(bot_native));
    });
    interpreter.run();
};

describe('TicksInterface ↔ nbsp engine parity (the "undefined is not a function" bug)', () => {
    it('CONTROL — a Bot.* name missing from the interface crashes bot code with the literal user-facing message', () => {
        // Exactly what the sandbox looked like before the fix for turbo-markets blocks.
        expect(() =>
            runBotScriptOnce({ purchase: () => {} }, "Bot.ntAnalyseTurboMarkets('R_50');")
        ).toThrow('undefined is not a function');
    });

    it('FIX — ntAnalyseTurboMarkets / ntTurboMarketsDecision are exposed and delegate to the engine', () => {
        const engine = makeEngine();
        const bot = { ...getTicksInterface(engine) };

        runBotScriptOnce(bot, "Bot.ntAnalyseTurboMarkets('R_50,R_100', 'DIGITOVER', 4, 1.95, 120, 0);");
        expect(engine.ntAnalyseTurboMarkets).toHaveBeenCalledWith('R_50,R_100', 'DIGITOVER', 4, 1.95, 120, 0);

        runBotScriptOnce(bot, "Bot.ntTurboMarketsDecision('reason');");
        expect(engine.ntTurboMarketsDecision).toHaveBeenCalledWith('reason');
    });

    it('every interface entry delegates to a trade engine method of the SAME name', () => {
        const engine = makeEngine();
        const ticks_interface = getTicksInterface(engine);
        expect(Object.keys(ticks_interface).length).toBeGreaterThan(0);

        for (const [name, fn] of Object.entries(ticks_interface)) {
            expect(typeof fn).toBe('function');
            fn('probe', 1);
            expect(engine[name]).toHaveBeenCalledWith('probe', 1);
        }
    });

    it('exposes every nt* analysis/decision bridge the NeuroTrade blocks can emit', () => {
        // Names generated by scratch/blocks/Binary/Tick Analysis/neurotrade_*.js.
        // If a block generator adds a new Bot.nt* call, add its interface entry
        // in TicksInterface/BotInterface AND here — otherwise the js-interpreter
        // serves the user "undefined is not a function" again.
        const EXPECTED_BRIDGES = [
            'ntAnalyseDigitMarkets',
            'ntDigitDecision',
            'ntAnalyseContracts',
            'ntContractDecision',
            'ntAnalyseHedge',
            'ntHedgeDecision',
            'ntAnalyseSurgeMarkets',
            'ntSurgeDecision',
            'ntAnalyseTurboRecovery',
            'ntTurboRecoveryDecision',
            'ntAnalyseTurboMarkets',
            'ntTurboMarketsDecision',
            'ntAnalyseDualLockEntry',
            'ntDualLockEntryDecision',
            'ntAnalyseBastionEntry',
            'ntBastionEntryDecision',
            'ntSwitchMarket',
        ];
        const ticks_interface = getTicksInterface(makeEngine());
        for (const name of EXPECTED_BRIDGES) {
            expect(ticks_interface).toHaveProperty(name);
            expect(typeof ticks_interface[name]).toBe('function');
        }
    });
});
